106	                            Element element1 = (Element)node2;
107	                            String excName=element1.getAttribute(EXCERCISE_NAME_TAG);
108	                            ExerciseType type = ExerciseType.valueOf(element1.getAttribute(EXCERCISE_TYPE_TAG));
