135	                                    dexc.setAdditionalWeightActivated(doubleValue!=Double.MAX_VALUE);
136	                                    dexc.setAdditionalWeight(doubleValue);
137	
138	                                    intValue=Integer.valueOf(element1.getAttribute(EXCERCISE_BACK_TAG));
139	                                    dexc.setBackActivated(intValue!=Integer.MAX_VALUE);
140	                                    dexc.setBackPosition(intValue);
141	
