202	    public boolean writeFile(File writeableFile) {
203	        try {
204	            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
205	            DocumentBuilder builder = factory.newDocumentBuilder();
206	
207	            Document doc = builder.newDocument();
208	
209	            Element rootElement = doc.createElement(ROOT_ID);
210	            Attr appversionAttr = doc.createAttribute(APPVERSION_ID);
211	            appversionAttr.setValue(CurrentApplicationVersion);
212	            rootElement.setAttributeNode(appversionAttr);
213	            doc.appendChild(rootElement);
214	
215	            for (Schedule sched : ApplicationModel.getSchedulesList()) {
216	                Element scheduleElement = doc.createElement(SCHEDULE_ID);
217	
218	//                Attr scheduleName=doc.createAttribute(SCHEDULE_NAME_TAG);
219	//                scheduleName.setValue(sched.getName());
220	//                scheduleElement.setAttributeNode(scheduleName);
221	                scheduleElement.setAttribute(SCHEDULE_NAME_TAG, sched.getName());
222	//                scheduleElement.setAttribute(SCHEDULE_TRAININGSTYPE_TAG, sched.getTrainingsType().name());
223	                scheduleElement.setAttribute(SCHEDULE_REPETITIONS_TAG, String.valueOf(sched.getRepetitions()));
224	                scheduleElement.setAttribute(SCHEDULE_PAUSETIME_TAG, String.valueOf(sched.getPauseTime()));
225	                scheduleElement.setAttribute(SCHEDULE_SETS_TAG, String.valueOf(sched.getSets()));
226	                scheduleElement.setAttribute(SCHEDULE_SPEED_TAG, String.valueOf(sched.getSpeed()));
227	
228	                for (Exercise exc : sched.exercises()) {
229	                    Element exerElement = doc.createElement(EXCERCISE_ID);
230	                    exerElement.setAttribute(EXCERCISE_NAME_TAG, exc.getName());
231	                    exerElement.setAttribute(EXCERCISE_POSITION_TAG, String.valueOf(exc.getPosition()));
232	                    exerElement.setAttribute(EXCERCISE_TYPE_TAG, exc.type().name());
233	                    switch (exc.type()) {
234	                        case Device:
235	                            DeviceExercise dexc = (DeviceExercise) exc;
236	                            exerElement.setAttribute(EXCERCISE_SEAT_TAG, String.valueOf(dexc.getSeatPosition()));
237	                            exerElement.setAttribute(EXCERCISE_LEG_TAG, String.valueOf(dexc.getLegPosition()));
238	                            exerElement.setAttribute(EXCERCISE_FOOT_TAG, String.valueOf(dexc.getFootPosition()));
239	                            exerElement.setAttribute(EXCERCISE_ANGLE_TAG, String.valueOf(dexc.getAnglePosition()));
240	                            exerElement.setAttribute(EXCERCISE_WEIGHT_TAG, String.valueOf(dexc.getWeight()));
241	                            exerElement.setAttribute(EXCERCISE_ADDITIONALWEIGHT_TAG, String.valueOf(dexc.getAdditionalWeight()));
242	                            exerElement.setAttribute(EXCERCISE_BACK_TAG, String.valueOf(dexc.getBackPosition()));
243	                            exerElement.setAttribute(EXCERCISE_DEVICENUMBER_TAG, String.valueOf(dexc.getDeviceNumber()));
244	                            break;
245	                        case BodyWeight:
246	                            BodyWeightExercise bexc = (BodyWeightExercise) exc;
247	                            exerElement.appendChild(doc.createTextNode(bexc.getAdditionalInformation()));
248	                            break;
249	                        case WarmUp:
250	                            WarmUpExercise wexc = (WarmUpExercise) exc;
251	                            exerElement.setAttribute(EXCERCISE_EXECUTIONTIME_TAG, String.valueOf(wexc.getExecutionTime()));
252	                            exerElement.setAttribute(EXCERCISE_INTENSITY_TAG, wexc.getIntenity().name());
253	                            exerElement.setAttribute(EXCERCISE_SUBINTENSITY_TAG, String.valueOf(wexc.getSubIntensity()));
254	                            exerElement.setAttribute(EXCERCISE_BPM_TAG, String.valueOf(wexc.getBPM()));
255	                            break;
256	                    }
257	
258	                    scheduleElement.appendChild(exerElement);
259	                }
260	
261	                rootElement.appendChild(scheduleElement);
262	
263	                DOMSource source = new DOMSource(doc);
264	
265	                TransformerFactory transformerFactory = TransformerFactory.newInstance();
266	                Transformer transformer = transformerFactory.newTransformer();
267	                StreamResult result = new StreamResult(writeableFile);
268	                transformer.transform(source, result);
269	            }
270	
