public class RoundTrip {
    static int fails = 0;
    static void check(String what, Object exp, Object act) {
        boolean ok = (exp == null ? act == null : exp.equals(act));
        if (!ok) fails++;
        System.out.println((ok ? "PASS " : "FAIL ") + what + " expected=" + exp + " actual=" + act);
