        wp.setCurrentApplicationVersion("1902");
        check("writeFile returned", Boolean.TRUE, wp.writeFile(f));

        String xml = new String(Files.readAllBytes(f.toPath()));
        System.out.println("--- written XML ---\n" + xml + "\n-------------------");
        check("XML contains trainingstype attr", Boolean.TRUE, xml.contains("trainingstype=\"maximum_strength\""));

        Model in = new Model();
        XMLParser rp = new XMLParser(in);
        check("parseFile returned", Boolean.TRUE, rp.parseFile(f));
        Schedule back = in.getSchedule("MySchedule");
        check("round-tripped trainings type", TrainingsTypes.maximum_strength, back.getTrainingsType());
        check("round-tripped reps", 12, back.getRepetitions());

        // legacy file with no trainingstype attribute must not crash
